//! A canonical package shadow must keep the source map's actual generated bytes.
use std::{fs, path::PathBuf};

use super::VirtualProject;

const INPUT: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../tests/_fixtures/differential/typechecker/mixed-vue-package-imports-11253/input.json"
));

fn project(main: Option<&str>) -> (tempfile::TempDir, VirtualProject, PathBuf) {
    let directory = tempfile::tempdir().unwrap();
    let root = vize_carton::path::canonicalize_non_verbatim(directory.path());
    let input: serde_json::Value = serde_json::from_str(INPUT).unwrap();
    assert_eq!(
        input["id"],
        "typechecker/regression/mixed-vue-package-imports-11253"
    );
    for file in input["files"].as_array().unwrap() {
        let name = file["path"].as_str().unwrap();
        let source = if name == "src/main.ts" {
            main.unwrap_or_else(|| file["source"].as_str().unwrap())
        } else {
            file["source"].as_str().unwrap()
        };
        let path = root.join(name);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, source).unwrap();
    }
    let main = root.join("src/main.ts");
    let mut project = VirtualProject::new(&root).unwrap();
    project.register_path(&main).unwrap();
    project.reconcile_package_routes_for_importers(std::slice::from_ref(&main));
    let bindings = project.package_routes_snapshot();
    let private = bindings
        .iter()
        .find(|binding| binding.importer_path == main && binding.specifier == "#src/plain")
        .expect("the exact authored private import must have a binding");
    assert!(private.route.is_some());
    // As in CLI preparation, absorb the complete source set while the package
    // route is active, so every package source enters its topology index.
    project
        .register_paths(&[
            root.join("src/App.vue"),
            main.clone(),
            root.join("src/plain.ts"),
        ])
        .unwrap();
    project.register_package_route_targets().unwrap();
    project.finalize_package_routes().unwrap();
    (directory, project, main)
}

#[test]
fn canonical_self_shadow_keeps_generated_bytes_and_authored_diagnostic_positions() {
    let (_directory, project, main) = project(None);
    let file = project.find_by_original(&main).unwrap();
    let canonical = file.virtual_path.clone();
    let expected = file.content.clone();
    let authored = project.original_content_for_virtual(&canonical).unwrap();
    assert_eq!(
        expected.as_str(),
        authored.replace("\"./App.vue\"", "\"./App.vue.ts\"")
    );
    assert_eq!(
        project.package_shadow_files.get(&canonical),
        Some(&canonical)
    );
    project.materialize().unwrap();
    assert_eq!(fs::read_to_string(&canonical).unwrap(), expected.as_str());
    assert!(project.find_by_diagnostic_virtual(&canonical).is_some());
    // The mapping API uses zero-based LSP coordinates; CLI errors use 4:7.
    let (path, line, column) = project.map_to_virtual(&main, 3, 6).unwrap();
    assert_eq!(path, canonical);
    let original = project.map_to_original(&path, line, column).unwrap();
    assert_eq!(original.path, main);
    assert_eq!((original.line, original.column), (3, 6));
}

#[test]
fn relocated_typescript_shadow_keeps_authored_bytes_and_rejects_the_generated_map() {
    let (_directory, project, main) = project(None);
    let file = project.find_by_original(&main).unwrap();
    let canonical = &file.virtual_path;
    let shadow = project
        .package_shadow_files
        .iter()
        .find_map(|(shadow, owner)| (owner == canonical && shadow != canonical).then_some(shadow))
        .expect("the private imports route must own a distinct package copy");
    let authored = project.original_content_for_virtual(canonical).unwrap();
    assert_ne!(authored, file.content.as_str());
    assert_eq!(
        project
            .package_shadow_content(shadow, canonical)
            .unwrap()
            .as_str(),
        authored
    );
    assert!(project.find_by_diagnostic_virtual(shadow).is_none());
    project.materialize().unwrap();
    assert_eq!(fs::read_to_string(shadow).unwrap(), authored);
}

#[test]
fn same_line_import_growth_maps_across_unicode_and_crlf_without_losing_the_file() {
    let source = "// 雪🍣\r\nimport App from \"./App.vue\"; const probe: number = \"bad\";\r\nimport { value } from \"#src/plain\";\r\nexport { App, value, probe };\r\n";
    let (_directory, project, main) = project(Some(source));
    let canonical = project
        .find_by_original(&main)
        .unwrap()
        .virtual_path
        .clone();
    project.materialize().unwrap();
    assert!(project.find_by_diagnostic_virtual(&canonical).is_some());
    let column = source.lines().nth(1).unwrap().find("probe").unwrap() as u32;
    let (path, line, virtual_column) = project.map_to_virtual(&main, 1, column).unwrap();
    assert_eq!((line, virtual_column), (1, column + 3));
    let original = project
        .map_to_original(&path, line, virtual_column)
        .unwrap();
    assert_eq!((original.line, original.column), (1, column));
}
